using System;using System.IO;using System.Collections;using System.Reflection;using UnityEngine;using Bokumyaku.Presentation;
public static class ReducedFlashCheck{
public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");var flags=BindingFlags.Instance|BindingFlags.NonPublic;var w=(InkBattleWorld)typeof(BokumyakuGame).GetField("battleWorld",flags).GetValue(g);var surface=typeof(BokumyakuGame).GetField("persistentInk",flags).GetValue(g);var texture=(Texture2D)surface.GetType().GetProperty("Texture").GetValue(surface);var list=(IList)typeof(InkBattleWorld).GetField("effects",flags).GetValue(w);for(int n=0;n<90;n++){w.BeforeTick(g.Run);g.Run.Tick();w.AfterTick(g.Run,false);if(g.Run.Attacks.Count>0)break;}w.Render(g.Run,texture,1,true,true,true,BokumyakuBattleHud.GetBattleViewport());int flashes=0;foreach(var e in list){var t=e.GetType();if(!(bool)t.GetField("flash").GetValue(e))continue;flashes++;if(((SpriteRenderer)t.GetField("renderer").GetValue(e)).enabled)throw new Exception("Flash still enabled");}if(flashes==0)throw new Exception("No flash sample");w.Render(g.Run,texture,1,true,false,true,BokumyakuBattleHud.GetBattleViewport());var result=new{passed=true,flashesSuppressed=flashes};File.WriteAllText(Path.GetFullPath("../docs/evidence/reduced-flash-check.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result));return result;}}
